patch:
diff --git a/repro-no-unused-expressions-use-strict.js b/repro-no-unused-expressions-use-strict.js
new file mode 100644
index 0000000..f214249
--- /dev/null
+++ b/repro-no-unused-expressions-use-strict.js
@@ -0,0 +1,46 @@
+"use strict";
+
+/*
+ * Reproduction: `no-unused-expressions` reports `'use strict'` (default parser,
+ * Espree) since 9.25.0. Exits 1 while the bug is present, 0 once it is fixed.
+ *
+ * Run from the repo root:  node repro-no-unused-expressions-use-strict.js
+ * Set ESLINT_API to test another ESLint install, e.g. a published 9.24.0.
+ */
+
+const { Linter } = require(process.env.ESLINT_API || "./lib/api");
+
+const linter = new Linter();
+const rules = { "no-unused-expressions": "error" };
+
+// The report's input: a `'use strict'` directive, linted with the default parser.
+const code = "'use strict';\nfoo();\n\nfunction f() {\n\t'use strict';\n\tbar();\n}\n";
+
+// core-js lints packages/core-js/** with `ecmaVersion: 3`. Others are controls.
+const versions = [3, 5, "latest"];
+let failed = false;
+
+for (const ecmaVersion of versions) {
+	const messages = linter.verify(code, [
+		{ languageOptions: { ecmaVersion, sourceType: "script" }, rules },
+	]);
+
+	console.log(
+		`ecmaVersion ${String(ecmaVersion).padEnd(6)} -> ${
+			messages.length
+				? messages
+						.map(m => `${m.line}:${m.column} ${m.message}`)
+						.join("; ")
+				: "no errors"
+		}`,
+	);
+	if (messages.length) {
+		failed = true;
+	}
+}
+
+if (failed) {
+	console.error("FAIL: no-unused-expressions reported a 'use strict' directive");
+	process.exit(1);
+}
+console.log("PASS: 'use strict' directives are not reported");
